/** The page's own game script, run on HTML inside root; env gives it the page's helpers. */
export function run(root, env) {
  const document = { getElementById: (id) => root.querySelector('#' + id), createElement: (t) => globalThis.document.createElement(t) };
  const { APP_LANG, el, cssVar, safeGet, safeSet, SCX } = env;
  let holdLangHook = null;
  (function(){
  const levels = [{"correct": 5, "max": 20, "unit": "m s⁻²", "en": "A force of 20 N acts on a 4 kg crate. Guess its acceleration.", "ta": "4 kg பெட்டி மேல 20 N விசை தாக்குது. அதோட முடுக்கத்த யூகி."}, {"correct": 18, "max": 60, "unit": "N", "en": "A 6 kg trolley accelerates at 3 m s⁻². Guess the unbalanced force acting on it.", "ta": "6 kg தள்ளுவண்டி 3 m s⁻² முடுக்கத்துல போகுது. அதுமேல தாக்குற சமநிலையற்ற விசைய யூகி."}, {"correct": 5, "max": 20, "unit": "kg", "en": "A force of 45 N gives an object an acceleration of 9 m s⁻². Guess its mass.", "ta": "45 N விசை ஒரு பொருளுக்கு 9 m s⁻² முடுக்கம் கொடுக்குது. அந்த பொருளோட திணிவ யூகி."}, {"correct": 24, "max": 100, "unit": "kg m s⁻¹", "en": "A 3 kg ball moves at 8 m s⁻¹. Guess its momentum.", "ta": "3 kg பந்து 8 m s⁻¹ வேகத்துல போகுது. அதோட உந்தத்த யூகி."}, {"correct": 6, "max": 20, "unit": "m s⁻²", "en": "Boss level! A 4 kg trolley is pushed with 30 N while friction resists with 6 N. Guess its acceleration (use the NET force).", "ta": "பாஸ் லெவல்! 4 kg தள்ளுவண்டிய 30 N விசையால தள்றோம், உராய்வு 6 N தடுக்குது. அதோட முடுக்கத்த யூகி (நிகர விசைய உபயோகி!)."}];
  const STAR_KEY = 'scx_force_stars';
  const levelRow = document.getElementById('holdLevelRow');
  const levelDesc = document.getElementById('holdLevelDesc');
  const holdSvg = document.getElementById('holdSvg');
  const guessSlider = document.getElementById('holdGuessSlider');
  const guessVal = document.getElementById('holdGuessVal');
  const unitEl = document.getElementById('holdUnit');
  const checkBtn = document.getElementById('holdCheckBtn');
  const resultEl = document.getElementById('holdResult');
  const starsEl = document.getElementById('holdStars');

  let curLevel = 0;
  let bestStars = [0,0,0,0,0];
  try{ const p = JSON.parse(safeGet(STAR_KEY) || '[0,0,0,0,0]'); if(Array.isArray(p) && p.length === 5) bestStars = p; }catch(e){}

  function drawScene(offset){
    holdSvg.innerHTML = '';
    holdSvg.appendChild(el('line',{x1:20,y1:92,x2:540,y2:92,stroke:cssVar('--text-faint'),'stroke-width':3,'stroke-linecap':'round'}));
    holdSvg.appendChild(el('line',{x1:480,y1:30,x2:480,y2:92,stroke:cssVar('--accent-3'),'stroke-width':3,'stroke-dasharray':'5 4'}));
    holdSvg.appendChild(el('polygon',{points:'480,30 510,40 480,50',fill:cssVar('--accent-3')}));
    const x = (offset===null) ? 110 : Math.max(60, Math.min(520, 450 + offset*6));
    holdSvg.appendChild(el('rect',{x:x-26,y:54,width:52,height:38,rx:5,fill:cssVar('--accent'),stroke:cssVar('--bg'),'stroke-width':2}));
    holdSvg.appendChild(el('line',{x1:x-26,y1:73,x2:x+26,y2:73,stroke:cssVar('--bg'),'stroke-width':2}));
    holdSvg.appendChild(el('line',{x1:x-70,y1:73,x2:x-30,y2:73,stroke:cssVar('--accent-2'),'stroke-width':4,'stroke-linecap':'round'}));
    holdSvg.appendChild(el('polygon',{points:(x-30)+',65 '+(x-30)+',81 '+(x-18)+',73',fill:cssVar('--accent-2')}));
  }

  function renderLevelRow(){
    levelRow.innerHTML = '';
    levels.forEach((lv,i)=>{
      const b = document.createElement('div');
      b.className = 'level-btn' + (i===curLevel ? ' active' : '');
      const stars = bestStars[i] || 0;
      b.innerHTML = '<div class="lnum2">'+(i+1)+'</div><div class="lstars">'+('★'.repeat(stars)+'☆'.repeat(3-stars))+'</div>';
      b.addEventListener('click', ()=>{ curLevel = i; loadLevel(); });
      levelRow.appendChild(b);
    });
  }
  function loadLevel(){
    renderLevelRow();
    const lv = levels[curLevel];
    levelDesc.textContent = (APP_LANG==='ta') ? lv.ta : lv.en;
    guessSlider.max = lv.max; guessSlider.value = 0; guessVal.textContent = '0';
    unitEl.textContent = lv.unit;
    resultEl.textContent = ''; resultEl.className = 'game-result';
    starsEl.textContent = '';
    drawScene(null);
  }
  guessSlider.addEventListener('input', ()=>{ guessVal.textContent = guessSlider.value; });

  checkBtn.addEventListener('click', ()=>{
    const lv = levels[curLevel];
    const guess = parseFloat(guessSlider.value);
    const err = Math.abs(guess - lv.correct);
    let stars;
    if(err <= 0.5) stars = 3;
    else if(err <= lv.max*0.02) stars = 2;
    else if(err <= lv.max*0.05) stars = 1;
    else stars = 0;
    drawScene(Math.max(-25, Math.min(25, (guess - lv.correct) * (25 / (lv.max*0.25)))));
    if(stars === 0){
      resultEl.textContent = (APP_LANG==='ta') ? '😅 நல்ல முயற்சி! சரியான பதில் '+lv.correct+' '+lv.unit+'.' : '😅 Nice try! The correct answer was '+lv.correct+' '+lv.unit+'.';
      resultEl.className = 'game-result lose';
      SCX.sndWrong();
    } else {
      resultEl.textContent = (APP_LANG==='ta') ? '🎉 சரியான பதில் = '+lv.correct+' '+lv.unit+'!' : '🎉 Correct answer: '+lv.correct+' '+lv.unit+'!';
      resultEl.className = 'game-result win';
    }
    starsEl.textContent = stars>0 ? ('★'.repeat(stars) + '☆'.repeat(3-stars)) : '';

    const prevBest = bestStars[curLevel] || 0;
    if(stars > prevBest){
      bestStars[curLevel] = stars;
      safeSet(STAR_KEY, JSON.stringify(bestStars));
      if(stars>0) SCX.pushItLevelResult(stars, bestStars.every(s=>s>0));
    } else if(stars>0){
      SCX.sndCorrect();
    }
    renderLevelRow();
  });

  loadLevel();
  holdLangHook = function(){ levelDesc.textContent = (APP_LANG==='ta') ? levels[curLevel].ta : levels[curLevel].en; renderLevelRow(); };
})();
  return { lang: () => holdLangHook && holdLangHook() };
}
